/* ============================================================
   CONFIGURAÇÃO DO E-MAIL (EmailJS - gratuito, sem backend)
   1. Crie uma conta em https://www.emailjs.com/
   2. Adicione um "Email Service" (ex: Gmail) -> copie o SERVICE_ID
   3. Crie um "Email Template" com variáveis: {{para_email}}, {{tipo}},
      {{detalhes}}, {{dia}}, {{hora}}, {{mensagem_dela}} -> copie o TEMPLATE_ID
   4. Em Account > General, copie sua "Public Key"
   5. Substitua os 4 valores abaixo.
   ============================================================ */
  const EMAILJS_PUBLIC_KEY  = CONFIG.EMAILJS_PUBLIC_KEY;
  const EMAILJS_SERVICE_ID  = CONFIG.EMAILJS_SERVICE_ID;
  const EMAILJS_TEMPLATE_ID = CONFIG.EMAILJS_TEMPLATE_ID;
  const DESTINATION_EMAIL   = CONFIG.DESTINATION_EMAIL;; // seu e-mail, pra onde a resposta dela vai

  let emailReady = false;
  try{
    if (window.emailjs && EMAILJS_PUBLIC_KEY !== "SUA_PUBLIC_KEY_AQUI"){
      emailjs.init({ publicKey: EMAILJS_PUBLIC_KEY });
      emailReady = true;
    }
  }catch(e){ console.warn("EmailJS não inicializado:", e); }

