/* ============================================================
   SOM (Web Audio API — sem precisar de arquivos de áudio)
   ============================================================ */
  let audioCtx = null;
  function getCtx(){
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx;
  }
  function playTone(freq, duration, type){
    try{
      const ctx = getCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type || "sine";
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.08, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
      osc.connect(gain).connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + duration);
    }catch(e){ /* som é só um bônus, ignora se falhar */ }
  }
  function playClick(){ playTone(660, 0.08, "sine"); }
  function playBell(){
    playTone(880, 0.35, "sine");
    setTimeout(()=>playTone(1320, 0.4, "sine"), 120);
  }
  document.addEventListener("click", (e)=>{
    if (e.target.closest("button")) playClick();
  });

/* ============================================================
   CONFETE 🎉
   ============================================================ */
  const confettiColors = ["#ff6fa5","#ffc94a","#ff8fb8","#ffd3e0","#b24c77"];
  const confettiShapes = ["💗","🎉","✨","💕","🌸"];
  function launchConfetti(){
    const layer = document.getElementById("confettiLayer");
    for (let i=0; i<40; i++){
      const piece = document.createElement("div");
      piece.className = "confetti-piece";
      const useEmoji = Math.random() > 0.5;
      if (useEmoji){
        piece.textContent = confettiShapes[Math.floor(Math.random()*confettiShapes.length)];
        piece.style.fontSize = (14 + Math.random()*14) + "px";
      } else {
        piece.style.width = "8px";
        piece.style.height = "14px";
        piece.style.background = confettiColors[Math.floor(Math.random()*confettiColors.length)];
        piece.style.borderRadius = "2px";
      }
      piece.style.left = Math.random()*100 + "%";
      piece.style.setProperty("--rot", (Math.random()*720-360) + "deg");
      const duration = 2.2 + Math.random()*1.6;
      piece.style.animationDuration = duration + "s";
      piece.style.animationDelay = (Math.random()*0.3) + "s";
      layer.appendChild(piece);
      setTimeout(()=>piece.remove(), (duration+0.3)*1000);
    }
  }

