/* ============================================================
   TELA 4 — CALENDÁRIO (semana atual + próxima)
   ============================================================ */
  const DOW = ["dom","seg","ter","qua","qui","sex","sáb"];
  const MONTHS = ["jan","fev","mar","abr","mai","jun","jul","ago","set","out","nov","dez"];

  function renderCalendarStep(){
    const flow = FLOWS[state.type];
    const today = new Date();
    today.setHours(0,0,0,0);
    let daysHtml = "";
    for (let i=0; i<6; i++){
      const d = new Date(today);
      d.setDate(today.getDate()+i);
      const iso = d.toISOString().slice(0,10);
      const label = `${d.getDate()} ${MONTHS[d.getMonth()]}`;
      if (i === 0) daysHtml += `<div class="calendar-week-label" style="grid-column:1/-1;">Essa semana</div>`;
      if (i === 7) daysHtml += `<div class="calendar-week-label" style="grid-column:1/-1;">Semana que vem</div>`;
      daysHtml += `<button class="day-btn" data-iso="${iso}" data-label="${DOW[d.getDay()]}, ${label}">
                     <span class="dow">${DOW[d.getDay()]}</span><span class="num">${d.getDate()}</span>
                   </button>`;
    }
     render(`
      ${progressDots(flow, "dia")}
      <span class="eyebrow">${flow.label}</span>
      <h1>Escolhe o dia 📅</h1>
      <div class="calendar-grid">${daysHtml}</div>
      <span class="back-link" id="backBtn">‹ voltar</span>
    `);
    document.querySelectorAll(".day-btn").forEach(btn=>{
      btn.addEventListener("click", ()=>{
        document.querySelectorAll(".day-btn").forEach(b=>b.classList.remove("selected"));
        btn.classList.add("selected");
        state.dayISO = btn.dataset.iso;
        state.dayLabel = btn.dataset.label;
        setTimeout(renderTimeStep, 180);
      });
    });
    document.getElementById("backBtn").addEventListener("click", ()=>{
      if (flow.hasLocation) renderLocationStep();
      else if (flow.hasFoodType) renderFoodTypeStep();
      else renderTypeSelect();
    });
  }

