/* ============================================================
   TELA 6 — CONFIRMAÇÃO (com texto digitando, contagem, .ics,
   campo de mensagem de volta) + ENVIO DE E-MAIL
   ============================================================ */
  const FOOD_PHRASES = {
    "Fast Food": "de fast food",
    "Churrascaria": "numa churrascaria",
    "Jantar": "",
    "Comida Japonesa": "de comida japonesa"
  };

  function buildConfirmSentence(flow){
    let extra = "";
    if (flow.hasLocation) extra = `, em <b>${state.subOption}</b>`;
    else if (flow.hasFoodType) {
      const phrase = FOOD_PHRASES[state.subOption] ?? "";
      extra = phrase ? ` ${phrase}` : "";
    }
    return {
      html: `Você tem ${flow.article} <b>${flow.naturalName}</b>${extra} comigo, no dia <b>${state.dayLabel}</b> às <b>${state.time}h</b>. Esteja pronta que irei te buscar! 🚗💨`,
      extra
    };
  }

  // ===== FUNÇÃO CORRIGIDA =====
  function typeWriter(el, html, speed){
    // separa tags de texto pra "digitar" só o texto e manter as tags intactas
    const container = document.createElement("div");
    container.innerHTML = html;
    el.innerHTML = "";
    const cursor = document.createElement("span");
    cursor.className = "typing-cursor";
    cursor.textContent = "\u00A0";
    el.appendChild(cursor);

    function typeNode(srcNode, destParent, done){
      const children = Array.from(srcNode.childNodes);
      let i = 0;
      function next(){
        if (i >= children.length){ done(); return; }
        const node = children[i];
        i++;
        if (node.nodeType === Node.TEXT_NODE){
          let charIdx = 0;
          const text = node.textContent;
          const span = document.createTextNode("");
          destParent.appendChild(span);
          el.appendChild(cursor); // mantém o cursor sempre no final do elemento raiz
          function typeChar(){
            if (charIdx <= text.length){
              span.textContent = text.slice(0, charIdx);
              charIdx++;
              el.appendChild(cursor);
              setTimeout(typeChar, speed);
            } else { next(); }
          }
          typeChar();
        } else {
          const clone = document.createElement(node.tagName);
          destParent.appendChild(clone);
          el.appendChild(cursor);
          typeNode(node, clone, next);
        }
      }
      next();
    }

    typeNode(container, el, ()=>{ cursor.remove(); });
  }
  // ===== FIM DA FUNÇÃO CORRIGIDA =====

  function pad(n){ return n.toString().padStart(2,"0"); }

  function getEventDate(){
    const [h,m] = state.time.split(":").map(Number);
    const d = new Date(state.dayISO + "T00:00:00");
    d.setHours(h, m, 0, 0);
    return d;
  }

  function startCountdown(el){
    function tick(){
      const now = new Date();
      const target = getEventDate();
      let diff = target - now;
      if (diff <= 0){ el.innerHTML = "é hoje/já passou! 💗"; return; }
      const days = Math.floor(diff / (1000*60*60*24));
      diff -= days*(1000*60*60*24);
      const hours = Math.floor(diff / (1000*60*60));
      diff -= hours*(1000*60*60);
      const mins = Math.floor(diff / (1000*60));
      el.innerHTML = `faltam <b>${days}d ${pad(hours)}h ${pad(mins)}m</b> 💕`;
    }
    tick();
    setInterval(tick, 30000);
  }

  function downloadICS(flow){
    const start = getEventDate();
    const end = new Date(start.getTime() + 2*60*60*1000);
    function fmt(d){
      return d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+"T"+pad(d.getHours())+pad(d.getMinutes())+"00";
    }
    const title = `Encontro: ${flow.naturalName}`;
    const desc = state.subOption ? `${flow.label} - ${state.subOption}` : flow.label;
    const ics = [
      "BEGIN:VCALENDAR","VERSION:2.0","BEGIN:VEVENT",
      "UID:"+Date.now()+"@convite-ludmila",
      "DTSTART:"+fmt(start),
      "DTEND:"+fmt(end),
      "SUMMARY:"+title,
      "DESCRIPTION:"+desc,
      "END:VEVENT","END:VCALENDAR"
    ].join("\r\n");
    const blob = new Blob([ics], { type: "text/calendar" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "encontro.ics";
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  }

  function renderConfirm(){
    const flow = FLOWS[state.type];
    const sentence = buildConfirmSentence(flow);
     render(`
      ${progressDots(flow, "pronto")}
      <div class="confirm-emoji">💖</div>
      <h1>Combinado!</h1>
      <p class="confirm-msg" id="confirmMsg"></p>
      <div class="countdown" id="countdownBox"></div>
      <label class="msg-label" for="herMsg">quer deixar um recadinho pra ele? (opcional)</label>
      <textarea class="msg-back" id="herMsg" placeholder="ex: mal posso esperar 💕"></textarea>
      <div class="action-row">
        <button class="btn-secondary" id="icsBtn">📅 Add. calendário</button>
        <button class="btn-secondary" id="sendMsgBtn">💌 Enviar recado</button>
      </div>
      <div id="statusMsg" class="status">enviando os detalhes... 💌</div>
    `);
    typeWriter(document.getElementById("confirmMsg"), sentence.html, 18);
    startCountdown(document.getElementById("countdownBox"));
    document.getElementById("icsBtn").addEventListener("click", ()=>downloadICS(flow));
    document.getElementById("sendMsgBtn").addEventListener("click", ()=>{
      sendEmail(flow, sentence.extra, document.getElementById("herMsg").value);
      document.getElementById("sendMsgBtn").textContent = "recado enviado 💗";
    });
    playBell();
    sendEmail(flow, sentence.extra, "");
  }

  function sendEmail(flow, extra, herMessage){
    const detalhesTexto = [
      `Tipo: ${flow.label}`,
      flow.hasLocation ? `Local: ${state.subOption}` : null,
      flow.hasFoodType ? `Tipo de comida: ${state.subOption}` : null,
      `Dia: ${state.dayLabel}`,
       `Horário: ${state.time}h`
    ].filter(Boolean).join(" | ");

    const statusEl = document.getElementById("statusMsg");

    if (!emailReady){
      const subject = encodeURIComponent("Ela escolheu o encontro! 💌");
      const bodyParts = [detalhesTexto];
      if (herMessage) bodyParts.push("Recado dela: " + herMessage);
      const body = encodeURIComponent(bodyParts.join("\n"));
      statusEl.textContent = "toque para confirmar o envio 💌";
      statusEl.style.cursor = "pointer";
      statusEl.style.textDecoration = "underline";
      statusEl.onclick = ()=>{
        window.location.href = `mailto:${DESTINATION_EMAIL}?subject=${subject}&body=${body}`;
      };
      return;
    }

    emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
      para_email: DESTINATION_EMAIL,
      tipo: flow.label,
      detalhes: detalhesTexto,
      dia: state.dayLabel,
      hora: state.time,
      mensagem_dela: herMessage || "(nenhuma)"
    }).then(()=>{
      statusEl.textContent = "prontinho, ele já sabe! 😘";
    }).catch((err)=>{
      console.error(err);
      statusEl.textContent = "não consegui enviar automaticamente 😕 (verifique a configuração do EmailJS)";
    });
  }

  renderInvite();